 (SELECT COUNT(*) FROM abt_variabel v JOIN (SELECT 12040 AS n, '08aae8c3ae38930b0e0360c2c3d408a9' AS h UNION ALL SELECT 12041 AS n, '757bfc864b643e1455cadc4bad64f5dc' AS h UNION ALL SELECT 12042 AS n, 'e059bbddcb403c1599cc4e66f0b15499' AS h UNION ALL SELECT 12043 AS n, '2e426f2fec620a724e60f908dda7ae34' AS h UNION ALL SELECT 12044 AS n, '5156ae2a602c499d9d1c872c2dd45c27' AS h UNION ALL SELECT 12045 AS n, '32c198f9058e534c245d702466c9b3bf' AS h UNION ALL SELECT 12046 AS n, '9a33368660efa82dc62e6e12f1a87aeb' AS h UNION ALL SELECT 12047 AS n, 'd1f2e1e227eb60d5eb1f30e16484c31e' AS h UNION ALL SELECT 12048 AS n, '4c9959ba4faf4114924ddb0dec7e045b' AS h UNION ALL SELECT 12049 AS n, '53f909811cc3edb19fe6e8cb7892ff90' AS h UNION ALL SELECT 12050 AS n, 'e756778512e7a03808345d52ed70fbe7' AS h UNION ALL SELECT 12051 AS n, '99513d7f2f9cb41910bbd7dd48f748e6' AS h UNION ALL SELECT 12052 AS n, 'ec6e1fd989f990b6786ae6bb4278426f' AS h UNION ALL SELECT 12053 AS n, 'bff87f0cd5b1ffa1e29b78a5cf4fb445' AS h UNION ALL SELECT 12054 AS n, 'da2e5df4121a9688d830098f7dd98326' AS h UNION ALL SELECT 12055 AS n, 'e2af27204f59e0dd0c109f417fdcf77b' AS h UNION ALL SELECT 12056 AS n, 'c1ab08065ca7edbfd076b0819dfc549d' AS h UNION ALL SELECT 12057 AS n, 'f85514dd9f0c10dfda6b08f2982ee072' AS h UNION ALL SELECT 12058 AS n, '4c3ca7c1b46537305effa4910980ae00' AS h UNION ALL SELECT 12059 AS n, 'a20453ba6a2dc6840b12c63995fd0496' AS h UNION ALL SELECT 12060 AS n, 'f1dea6e38a1c19f529ea04cbbe7cf691' AS h UNION ALL SELECT 12061 AS n, 'f983d194551caf70712f31eeddba9cbf' AS h UNION ALL SELECT 12062 AS n, '9ad465d623c2c7ed2a910f99af8f583d' AS h UNION ALL SELECT 12063 AS n, '4001fd9b79db4dbfe48e118eea038ad6' AS h UNION ALL SELECT 12064 AS n, 'e676a40fa35f21256616a0e491f7d341' AS h UNION ALL SELECT 12065 AS n, '85adb348414d4f8e21f1b541def6410b' AS h UNION ALL SELECT 12066 AS n, '4ed291541ba7e26ff397b15673b07b8b' AS h UNION ALL SELECT 12067 AS n, '6e59d297e94ec5f4171ec1301e1c1783' AS h UNION ALL SELECT 12068 AS n, 'daae