 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND ((routine_name = 'isian_bukti_baris' AND MD5(routine_definition) = '79a4943d4e9f1203877abffb12366c05') OR (routine_name = 'isian_bukti_sumber' AND MD5(routine_definition) = 'e2fbf7bee65300840897992612f4ef8e') OR (routine_name = 'isian_bukti_rtf' AND MD5(routine_definition) = '837bbefdb235de545fa4dce78c37ddf4'))),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_rtf_bukti', 'isian_rtf_bukti_nomor', 'isian_rtf_butir_rapi')),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_bukti_baris', 'isian_bukti_sumber', 'isian_bukti_rtf') AND NOT ((routine_name = 'isian_bukti_baris' AND MD5(routine_definition) = '79a4943d4e9f1203877abffb12366c05') OR (routine_name = 'isian_bukti_sumber' AND MD5(routine_definition) = 'e2fbf7bee65300840897992612f4ef8e') OR (routine_name = 'isian_bukti_rtf' AND MD5(routine_definition) = '837bbefdb235de545fa4dce78c37ddf4')))) AS p;
